class Solution:
    def countSquares(self, matrix: List[List[int]]) -> int:
        rows, cols = len(matrix), len(matrix[0])
        dp = [0] * cols
        total = 0

        for i in range(rows):
            prev_diag = 0
            for j in range(cols):
                above = dp[j]
                if matrix[i][j] == 1:
                    if i == 0 or j == 0:
                        dp[j] = 1
                    else:
                        dp[j] = 1 + min(prev_diag, dp[j], dp[j - 1])
                    total += dp[j]
                else:
                    dp[j] = 0
                prev_diag = above

        return total

