static int parse_int(const char **p) {
    int sign = 1;
    int value = 0;

    while (**p == ' ' || **p == '\n' || **p == '\r' || **p == '\t' || **p == ',') {
        (*p)++;
    }

    if (**p == '-') {
        sign = -1;
        (*p)++;
    }

    while (**p >= '0' && **p <= '9') {
        value = value * 10 + (**p - '0');
        (*p)++;
    }

    return value * sign;
