static int **parse_matrix(const char **p, int *rows, int **col_sizes) {
    const char *s = *p;
    while (*s && *s != '[') s++;
    if (!*s) return NULL;
    s++; /* outer matrix '[' */

    int **matrix = (int **)malloc(300 * sizeof(int *));
    int *cols = (int *)malloc(300 * sizeof(int));
    int row_count = 0;

    while (*s) {
        while (*s == ' ' || *s == '\n' || *s == '\r' || *s == '\t' || *s == ',') s++;

        if (*s == ']') {
            s++;
            break;
        }

        if (*s != '[') break;
        s++; /* row '[' */

        int *row = (int *)malloc(300 * sizeof(int));
        int col_count = 0;

        while (*s) {
            while (*s == ' ' || *s == '\n' || *s == '\r' || *s == '\t' || *s == ',') s++;

            if (*s == ']') {
                s++;
                break;
            }

            row[col_count++] = parse_int(&s);
        }

        matrix[row_count] = row;
        cols[row_count] = col_count;
        row_count++;
    }

    *rows = row_count;
    *col_sizes = cols;
    *p = s;
    return matrix;
}

int main(void) {
    static char line[1000000];

    if (!fgets(line, sizeof(line), stdin)) {
        return 0;
    }

    const char *p = line;
    while (*p && *p != '[') p++;
    p++; /* outer args '[' */

    int rows = 0;
    int *col_sizes = NULL;
    int **matrix = parse_matrix(&p, &rows, &col_sizes);

    int result = countSquares(matrix, rows, col_sizes);
    printf("%d\n", result);

    for (int i = 0; i < rows; ++i) {
        free(matrix[i]);
    }
    free(matrix);
    free(col_sizes);

    return 0;
}

