static vector<string> splitTopLevel(const string& s) {
    vector<string> parts;
    int depth = 0;
    size_t start = 0;

    for (size_t i = 0; i < s.size(); ++i) {
        if (s[i] == '[') ++depth;
        else if (s[i] == ']') --depth;
        else if (s[i] == ',' && depth == 0) {
            parts.push_back(s.substr(start, i - start));
            start = i + 1;
        }
    }

    if (start < s.size()) {
        parts.push_back(s.substr(start));
    }

    return parts;
}

static vector<int> parseIntArray(string s) {
    if (!s.empty() && s.front() == '[') {
        s = s.substr(1, s.size() - 2);
    }

    vector<int> result;
    if (s.empty()) return result;

    for (const string& part : splitTopLevel(s)) {
        result.push_back(stoi(part));
    }
    return result;
}

static vector<vector<int>> parseMatrix(string s) {
    if (!s.empty() && s.front() == '[') {
        s = s.substr(1, s.size() - 2);
    }

    vector<vector<int>> matrix;
    if (s.empty()) return matrix;

    for (const string& row : splitTopLevel(s)) {
        matrix.push_back(parseIntArray(row));
    }
    return matrix;
}

