import java.io.*;
import java.util.*;

class Solution {
    public int countSquares(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        int[] dp = new int[cols];
        int total = 0;

        for (int i = 0; i < rows; i++) {
            int prevDiag = 0;
            for (int j = 0; j < cols; j++) {
                int above = dp[j];

                if (matrix[i][j] == 1) {
                    if (i == 0 || j == 0) {
                        dp[j] = 1;
                    } else {
                        dp[j] = 1 + Math.min(prevDiag, Math.min(dp[j], dp[j - 1]));
                    }
                    total += dp[j];
                } else {
                    dp[j] = 0;
                }

                prevDiag = above;
            }
        }

        return total;
    }
}

public class Main {
    static List<String> splitTopLevel(String s) {
        List<String> parts = new ArrayList<>();
        int depth = 0;
        int start = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '[') depth++;
            else if (c == ']') depth--;
            else if (c == ',' && depth == 0) {
                parts.add(s.substring(start, i).trim());
                start = i + 1;
            }
        }
        if (start < s.length()) {
            parts.add(s.substring(start).trim());
        }
        return parts;
    }

    static int[] parseIntArray(String s) {
        s = s.trim();
        if (s.equals("[]")) return new int[0];
        String inner = s.substring(1, s.length() - 1);
        List<String> parts = splitTopLevel(inner);
        int[] result = new int[parts.size()];
        for (int i = 0; i < parts.size(); i++) {
            result[i] = Integer.parseInt(parts.get(i).trim());
        }
        return result;
    }

    static int[][] parseMatrix(String s) {
        s = s.trim();
        if (s.equals("[]")) return new int[0][0];
        String inner = s.substring(1, s.length() - 1);
        List<String> rows = splitTopLevel(inner);
        int[][] matrix = new int[rows.size()][];
        for (int i = 0; i < rows.size(); i++) {
            matrix[i] = parseIntArray(rows.get(i));
        }
        return matrix;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine().trim();

        int depth = 0;
        int matrixStart = line.indexOf('[', 1);
        int matrixEnd = matrixStart;
        while (matrixEnd < line.length()) {
            char c = line.charAt(matrixEnd);
            if (c == '[') depth++;
            else if (c == ']') {
                depth--;
                if (depth == 0) break;
            }
            matrixEnd++;
        }

        int[][] matrix = parseMatrix(line.substring(matrixStart, matrixEnd + 1));
        int result = new Solution().countSquares(matrix);
        System.out.println(result);
    }
}

